INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Advanced Defensive Handgun Level Four', 'Tampa Shooters Network', 'General Networking', 'Advanced Defensive Handgun Level Four (ADH4) **Course Brief:** This level of defensive pistol training is specifically designed to pick up', 'Advanced Defensive Handgun Level Four (ADH4) **Course Brief:** This level of defensive pistol training is specifically designed to pick up from where our ADH1 curriculum ended and continues to develop and refine the techniques to a deeper level of understanding. It will allow you to integrate more advanced techniques into your toolbox of pistol fighting systems. Topics covered include: One handed shooting and manipulation, point shooting, shooting while moving, use of cover, home defense More info: https://www.meetup.com/tampa-shooters-network/events/312790132/', '2026-10-18T09:00:00-04:00', 'Okeechobee Shooting Sports', '7055 NE 48th St', 'Okeechobee', 'FL', '', 27.98, -82.78, 'Tampa Shooters Network', 1, false, '$300', 'live', 'meetup', 'https://www.meetup.com/tampa-shooters-network/events/312790132/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
