INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Cincy .NET Users Group (CINNUG) and Architect Forum Monthly Meeting', 'TechLife Cincinnati', 'Tech & Software', 'Special thanks to Pintas & Mullins Law Firm ([Pintas & Mullins](https://www.pintas.com/)) for sponsoring us! We meet in the Office Key in', 'Special thanks to Pintas & Mullins Law Firm ([Pintas & Mullins](https://www.pintas.com/)) for sponsoring us! We meet in the Office Key in the Union Centre Office Park II building (9078 Union Centre Blvd). The conference room (Centre Pointe) is on the third floor. The doors lock promptly at 6, so if you will be late, send a message here. It will come to my email. CINNUG: Topic: **Playwright + AI: Teaching an Agent to Test Your App** Playwright has become a go-to framework for reliable end-to-end More info: https://www.meetup.com/techlife-cincinnati/events/314502670/', '2026-10-27T18:00:00-04:00', 'Office Key', '9078 Union Centre Blvd, suite 350', 'West Chester', 'OH', '', 39.27, -84.41, 'TechLife Cincinnati', 7, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/techlife-cincinnati/events/314502670/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('CINPA Monthly Meeting', 'TechLife Cincinnati', 'Tech & Software', 'DO NOT USE MEETUP RSVP - USE THE LINK in the text in the Comments N.B.: Check comments here (below) or', 'DO NOT USE MEETUP RSVP - USE THE LINK in the text in the Comments N.B.: Check comments here (below) or [http://www.cinpa.org/meeting-topic](http://www.cinpa.org/meeting-topic) each month for new meeting LINK. Cincinnati Networking Professionals Association - CINPA Monthly Meeting - FIRST WEDNESDAY - Typically we have an IT Industry professional present on a subject of interest. Oftentimes these are hardware, software or services vendors. Specific meeting information can be found at CINPA More info: https://www.meetup.com/techlife-cincinnati/events/316567892/', '2026-11-04T18:30:00-05:00', 'Online event', 'Online event', 'Cincinnati', 'OH', '', 39.27, -84.41, 'TechLife Cincinnati', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/techlife-cincinnati/events/316567892/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('NFT AI ART Columbus', 'TechLife Columbus', 'Founders & Startups', 'NFT''s are here to stay folks! This is a group for like minded people interested in understanding, leveraging, using, creating for,', 'NFT''s are here to stay folks! This is a group for like minded people interested in understanding, leveraging, using, creating for, profiting from, trading too i suppose, NFT''s.. everything around them, complexity, fear and exploits, best practices and more. **PLUS** This group will talk AI ART tools, techniques, artists, video, audio, prototypes and more in the AI assisted production space- ART specifically, but we can get into any aspect of some of the cooler things happening in AI in general. More info: https://www.meetup.com/techlifecolumbus/events/316708954/', '2026-10-15T09:30:00-04:00', 'The Point at Otterbein', '60 Collegeview Rd', 'Westerville', 'OH', '', 39.99, -83.04, 'TechLife Columbus', 2, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/techlifecolumbus/events/316708954/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
