INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate on Tap with Lalo', 'The Denver Real Estate Meetup', 'Real Estate', '**This Month''s Topic:** You love your low mortgage rate. But do you still love your house? If you’ve been wondering whether to move,', '**This Month''s Topic:** You love your low mortgage rate. But do you still love your house? If you’ve been wondering whether to move, remodel, rent out your current home, or stay put, join us for a candid conversation about how to weigh your options. We’ll talk through the financial side of the decision and the practical questions that matter just as much. We’ll cover: * When moving makes financial sense, even with today’s interest rates * Whether to spend money remodeling or put it toward your More info: https://www.meetup.com/the-denver-real-estate-meetup/events/316713586/', '2026-10-13T18:30:00-06:00', 'Resolute Brewing Tap & Cellar', '18148 W 92nd Ln, Suite 100', 'Arvada', 'CO', '', 39.7, -105.08, 'The Denver Real Estate Meetup', 12, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/the-denver-real-estate-meetup/events/316713586/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How to Beat a 7% Interest Rate - Webinar', 'The Denver Real Estate Meetup', 'Real Estate', 'A 7% interest rate does not automatically mean buying real estate is off the table. In fact, higher rates and longer days on market can', 'A 7% interest rate does not automatically mean buying real estate is off the table. In fact, higher rates and longer days on market can create opportunities buyers rarely see in a competitive seller’s market. In this webinar, we’ll break down creative ways to make a purchase work, including permanent and temporary rate buydowns, seller concessions, assumable mortgages, seller financing, rent-to-own agreements, house hacking and negotiating below the asking price. We’ll also show you how to More info: https://www.meetup.com/the-denver-real-estate-meetup/events/316669198/', '2026-10-14T12:00:00-06:00', 'Online event', 'Online event', 'Denver', 'CO', '', 39.7, -105.08, 'The Denver Real Estate Meetup', 15, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/the-denver-real-estate-meetup/events/316669198/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Beat Today''s Rates by Assuming Mortgages', 'The Denver Real Estate Meetup', 'Real Estate', 'Buying a home? Learn how assumable mortgages can help you access rates below 4% and save thousands on your next home. ### How to Get a', 'Buying a home? Learn how assumable mortgages can help you access rates below 4% and save thousands on your next home. ### How to Get a Mortgage Rate Below 4% in Today’s Market Mortgage rates have gone up, and they may continue to rise. Many “experts” said rates would be back in the 5s by now, but today’s market continues to challenge those expectations. Meanwhile, homeowners are sitting on mortgages with **rates below 4%**. And those mortgages **are assumable**. That creates an opportunity for More info: https://www.meetup.com/the-denver-real-estate-meetup/events/316856007/', '2026-10-21T18:00:00-06:00', 'To be announced', '', 'Denver', 'CO', '', 39.7, -105.08, 'The Denver Real Estate Meetup', 8, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/the-denver-real-estate-meetup/events/316856007/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The Denver Real Estate Meetup - STRs & Cost Segregation', 'The Denver Real Estate Meetup', 'Real Estate', 'You may have heard about using short-term rentals and cost segregation to build wealth, but how does it actually come together? Join The', 'You may have heard about using short-term rentals and cost segregation to build wealth, but how does it actually come together? Join The Denver Real Estate Meetup for a practical conversation with **Kevin Bevillard, CPA; Mike Stone, mortgage broker; and Chad Rocke, investor-friendly real estate agent.** Exactly one year ago, these three worked together to put this strategy into action. Now, they’re sharing the case study—from the property purchase and financing to the cost segregation process More info: https://www.meetup.com/the-denver-real-estate-meetup/events/316885100/', '2026-11-04T18:00:00-07:00', 'Jackson''s LODO', '1520 20th St', 'Denver', 'CO', '', 39.7, -105.08, 'The Denver Real Estate Meetup', 3, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/the-denver-real-estate-meetup/events/316885100/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Learn & Lunch with Linda at the Harris County Foreclosure Auction', 'The Houston Real Estate Investment Education Meetup', 'Real Estate', 'The **1st Tuesday of every month**, the Queen of Foreclosure hosts a LIVE, FREE tour and class at the monthly Harris County Foreclosure', 'The **1st Tuesday of every month**, the Queen of Foreclosure hosts a LIVE, FREE tour and class at the monthly Harris County Foreclosure Auction. There is a brief tour, explaining the ins and outs of the auction itself, and then a 45 minute mini-workshop that explains hot topics that foreclosure investors need to know, such as: * What happens to the liens after foreclosure? * What are post-judgment taxes? * What are redemptive rights and redemptive periods? * What is the difference between a More info: https://www.meetup.com/the-houston-real-estate-investment-education-meetup/events/zvjzwsyjcpbfb/', '2026-11-03T10:00:00-06:00', 'Bayou City Event Center', '9401 Knight Rd', 'Houston', 'TX', '', 29.72, -95.22, 'The Houston Real Estate Investment Education Meetup', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/the-houston-real-estate-investment-education-meetup/events/zvjzwsyjcpbfb/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
